INSERT INTO cps_inventory_txn (
    item_id, txn_type, qty, before_qty, after_qty, unit,
    operator_emp_no, operator_name, remark
) VALUES (
    #{itemId}, #{txnType}, #{qty}, #{beforeQty}, #{afterQty}, #{unit},
    #{operatorEmpNo}, #{operatorName}, #{remark}
)

mapper.select:
SELECT t.id, t.item_id, t.txn_type, t.qty, t.before_qty, t.after_qty, t.unit,
       t.operator_emp_no, t.operator_name, t.remark, t.created_at,
       i.item_code, i.item_name
FROM cps_inventory_txn t
JOIN cps_inventory_item i ON i.id = t.item_id
WHERE 1 = 1

  AND t.item_id = #{itemId}


  AND t.txn_type = #{txnType}

ORDER BY t.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM cps_inventory_txn t
WHERE 1 = 1

  AND t.item_id = #{itemId}


  AND t.txn_type = #{txnType}
